import { Worker } from 'worker_threads';
import { PHPRequest, PHPResponse, PHPRunOptions } from '@php-wasm/universal';
import { WPNowOptions } from 'vendor/wp-now/src/config';

// This allows TypeScript to pick up the magic constant that's auto-generated by Forge's Webpack
declare const PHP_WORKER_MODULE_PATH: string;

enum WorkerPoolStatus {
	INITIALIZING = 'initializing',
	READY = 'ready',
	SHUTTING_DOWN = 'shutting_down',
	SHUTDOWN = 'shutdown',
}

interface PendingRequestHandlers {
	resolve: ( value: PHPResponse ) => void;
	reject: ( error: any ) => void;
}

interface QueuedRequest extends PendingRequestHandlers {
	request: PHPRequest;
}

export class PHPWorkerPool {
	#status: WorkerPoolStatus = WorkerPoolStatus.INITIALIZING;
	// collection of worker instances
	#workers: Worker[] = [];
	// collection of workers ready to accept requests
	#readyWorkers = new Set< number >();
	// queue for requests that needs to be handled
	#requestQueue: QueuedRequest[] = [];
	// autoincrement counter to assign requests with an id
	#nextRequestId = 0;
	// requests that are currently being handled
	#pendingRequests = new Map< number, PendingRequestHandlers >();

	constructor(
		private options: WPNowOptions,
		private numWorkers: number
	) {}

	async initialize() {
		console.log( `Creating PHP Worker Pool with ${ this.numWorkers } workers` );
		console.log( 'Worker script path:', PHP_WORKER_MODULE_PATH );

		for ( let i = 0; i < this.numWorkers; i++ ) {
			console.log( `Initializing worker ${ i }...` );
			try {
				await this.initializeWorker( i );
			} catch ( error ) {
				console.error( `Failed to create worker ${ i }:`, error );
				throw error;
			}
		}

		console.log( 'Waiting for all workers to be ready...' );
		try {
			// Wait for all workers to be ready with a timeout
			const timeout = 10000; // 10 seconds timeout
			const workerPromises = this.#workers.map(
				( _, index ) =>
					new Promise< void >( ( resolve, reject ) => {
						const checkReady = () => {
							if ( this.#readyWorkers.has( index ) ) {
								console.log( `Worker ${ index } is ready` );
								resolve();
							} else {
								// console.log( `Worker ${ index } not ready yet, checking again in 100ms...` );
								setTimeout( checkReady, 100 );
							}
						};
						checkReady();

						// Add timeout
						setTimeout( () => {
							reject(
								new Error( `Worker ${ index } initialization timed out after ${ timeout }ms` )
							);
						}, timeout );
					} )
			);

			await Promise.all( workerPromises );
			console.log( 'All workers initialized and ready' );
			this.#status = WorkerPoolStatus.READY;
		} catch ( error ) {
			console.error( 'Worker pool initialization failed:', error );
			// Clean up any workers that did start
			await this.shutdown();
			throw error;
		}
	}

	private async initializeWorker( workerId: number ) {
		const worker = new Worker( PHP_WORKER_MODULE_PATH, {
			workerData: { options: this.options, workerId },
		} );

		worker.on( 'message', ( data ) => {
			console.log( `Worker ${ workerId } message:`, data.success, 'requestId', data.requestId );
			if ( data.type === 'ready' ) {
				console.log( `Worker ${ workerId } signaled ready` );
				this.#readyWorkers.add( workerId );
				this.processQueue();
			} else if ( data.type === 'error' ) {
				console.error( `Worker ${ workerId } initialization error:`, data.error );
				this.restartWorker( workerId );
			} else {
				const pending = this.#pendingRequests.get( data.requestId );
				if ( pending ) {
					if ( data.success ) {
						pending.resolve( data.response );
					} else {
						pending.reject( new Error( data.error ) );
					}
					this.#pendingRequests.delete( data.requestId );
					this.#readyWorkers.add( workerId );
					console.log( 'worker free again', workerId, 'lastRequestId', data.requestId );
					this.processQueue();
				}
			}
		} );

		worker.on( 'error', ( error ) => {
			console.error( `Worker ${ workerId } error:`, error );
			this.#readyWorkers.delete( workerId );

			this.restartWorker( workerId );
		} );

		worker.on( 'exit', ( code ) => {
			console.log( `Worker ${ workerId } exited with code ${ code }` );
			this.#readyWorkers.delete( workerId );

			if ( code === 0 ) {
				console.log( `Worker ${ workerId } exited` );
				delete this.#workers[ workerId ];
				const remainingWorkers = this.#workers
					.map( ( w, idx ) => ( w ? `${ idx }` : null ) )
					.filter( ( id ) => id !== null );
				const activeCount = remainingWorkers.length;
				console.log( `Workers: active=${ activeCount }, ids=[${ remainingWorkers.join( ',' ) }]` );
			} else {
				console.error( `Worker ${ workerId } crashed` );
				this.restartWorker( workerId );
			}
		} );

		this.#workers[ workerId ] = worker;
	}

	private restartWorker( workerId: number ) {
		if ( this.#status === WorkerPoolStatus.SHUTTING_DOWN ) return;
		this.initializeWorker( workerId ).catch( ( error ) => {
			console.error( `Failed to restart worker ${ workerId }:`, error );
		} );
	}

	private getNextWorker(): number {
		if ( this.areAllWorkersBusy() ) return -1;
		return Array.from( this.#readyWorkers )[ 0 ]; // return id of first available worker
	}

	private isQueueEmpty(): boolean {
		return this.#requestQueue.length === 0;
	}

	private areAllWorkersBusy(): boolean {
		return this.#readyWorkers.size === 0;
	}

	private processQueue() {
		if ( this.isQueueEmpty() ) {
			return;
		}

		if ( this.areAllWorkersBusy() ) {
			console.log( 'Waiting on a worker to be available' );
			return;
		}

		const workerId = this.getNextWorker();
		this.#readyWorkers.delete( workerId );

		const { resolve, reject, request } = this.#requestQueue.shift()!;
		const requestId = this.#nextRequestId++;

		this.#pendingRequests.set( requestId, { resolve, reject } );

		try {
			console.log( 'worker assigned', 'workerId', workerId, 'requestId', requestId );
			this.#workers[ workerId ].postMessage( { requestId, request } );
		} catch ( error ) {
			console.error( `Error sending message to worker ${ workerId }:`, error );
			this.restartWorker( workerId );
			this.#requestQueue.unshift( { resolve, reject, request } );
		}
	}

	async handleRequest( request: PHPRequest ): Promise< PHPResponse > {
		return new Promise( ( resolve, reject ) => {
			this.#requestQueue.push( { resolve, reject, request } );
			this.processQueue();
		} );
	}

	async shutdown() {
		if ( this.#status === WorkerPoolStatus.SHUTDOWN ) {
			console.log( 'Worker pool already shutdown' );
			return;
		}

		console.log( 'Shutting down worker pool...' );
		this.#status = WorkerPoolStatus.SHUTTING_DOWN;

		// Send shutdown message to all workers and collect their exit promises
		const workerExitPromises = this.#workers
			.map( ( worker, id ) => ( worker ? { worker, id } : null ) )
			.filter( ( entry ): entry is { worker: Worker; id: number } => entry !== null )
			.map( ( { worker } ) => {
				return new Promise< void >( ( resolve ) => {
					worker.once( 'exit', () => resolve() );
					worker.postMessage( { type: 'shutdown' } );
				} );
			} );

		// Wait for all workers to exit gracefully or timeout after 5 seconds
		try {
			await Promise.race( [
				Promise.all( workerExitPromises ),
				new Promise( ( _, reject ) =>
					setTimeout( () => reject( new Error( 'PHP worker shutdown timeout' ) ), 5000 )
				),
			] );
		} catch ( error ) {
			console.warn( 'Some workers did not exit gracefully:', error );
		}

		// Force terminate any remaining workers
		const remainingWorkers = this.#workers.filter( ( worker ) => worker !== null );
		if ( remainingWorkers.length > 0 ) {
			console.log( 'workers still left', remainingWorkers.length );
			await Promise.all( remainingWorkers.map( ( worker ) => worker.terminate() ) );
		}

		// Clear all internal state
		this.#workers = [];
		this.#readyWorkers.clear();
		this.#pendingRequests.clear();
		this.#requestQueue = [];

		this.#status = WorkerPoolStatus.SHUTDOWN;
		console.log( 'Worker pool shutdown completed' );
	}
}
